# and 0s everywhere else

min_row, max_row = 21, 23
min_col, max_col = 21, 24

output = []
for i in range(30):
    row = []
    for j in range(26):
        if i >= min_row - 1 and i <= max_row + 1 and j >= min_col - 1 and j <= max_col + 1:
            row.append(1)
        else:
            row.append(0)
    output.append(row)

print("Output rows around 7-region:")
for i in range(19, 26):
    print(f"Row {i}: {' '.join(str(c) for c in output[i])}")

